ALTER TABLE "GeofenceDeviceState" ADD CONSTRAINT "GeofenceDeviceState_trackedDeviceId_tenantId_fkey" FOREIGN KEY ("trackedDeviceId", "tenantId") REFERENCES "TrackedDevice"("id", "tenantId") ON DELETE CASCADE ON UPDATE CASCADE;

